import{_ as t,o as e,c as i,a as o}from"./app-be7ae715.js";const a={},r=o('<h4 id="git-repository" tabindex="-1"><a class="header-anchor" href="#git-repository" aria-hidden="true">#</a> Git Repository</h4><ol><li><code>git log &lt;--pretty=oneline | --graph&gt;</code> show previous commits</li><li><code>git relog</code></li></ol><h4 id="git-tag" tabindex="-1"><a class="header-anchor" href="#git-tag" aria-hidden="true">#</a> Git Tag</h4><ol><li><code>git tag -a &lt;tagname&gt; -m &quot;&lt;describe content&gt;&quot; &lt;branchHash&gt;</code></li><li><code>git tag &lt;tagname&gt; &lt;branchHash&gt;</code></li><li><code>git tag -d &lt;tagname&gt;</code></li><li><code>git push origin &lt;tanname&gt;</code></li><li><code>git push origin :refs/tags/&lt;tagname&gt;</code> 移除远程Tag</li></ol><h4 id="git-version" tabindex="-1"><a class="header-anchor" href="#git-version" aria-hidden="true">#</a> Git Version</h4><ol><li><code>git reset --hard HEAD^</code></li><li><code>git checkout -- &lt;file&gt;</code> 文件回退*到上一个版本(上一个commit/add)</li><li><code>git reset HEAD &lt;file&gt;</code> 取消暂存区的文件提交（文件不变）</li></ol><h4 id="git-remote" tabindex="-1"><a class="header-anchor" href="#git-remote" aria-hidden="true">#</a> Git Remote</h4><ol><li><code>git remote add origin git@github.com:&lt;user-name&gt;/&lt;repository&gt;</code>添加远程仓库</li><li><code>git remote -v</code> 查看远程版本库</li><li><code>git remote rm &lt;remote-name&gt;</code></li><li><code>git push &lt;--set-upstream | -u&gt; &lt;origin-repository&gt; &lt;branch-name&gt;</code> 推送并追踪上游远程分支</li></ol><h4 id="git-branchs" tabindex="-1"><a class="header-anchor" href="#git-branchs" aria-hidden="true">#</a> Git Branchs</h4><ol><li><code>git merge &lt;branch&gt;</code> 将对应分支的修改合并到本分支。当目标分支拉取后，本分支没有更新（目标分支和本分支在一条线上），默认使用<code>fast forward</code>模式，即将本分支的指针直接指向目标分支最新节点，删除目标分支后失去相关修改记录。使用<code>git merge --no-ff &lt;branch&gt;</code>后，会创建一个新的节点，分别指向目标分支和当前分支最新节，删除目标分支后，仍会有分叉记录。</li><li><code>git stash &lt;list | apply &lt;stash@{number}&gt; | drop | pop&gt;</code></li><li><code>git cherry-pick</code></li></ol>',10),l=[r];function c(d,g){return e(),i("div",null,l)}const s=t(a,[["render",c],["__file","Git.html.vue"]]);export{s as default};
